from pathlib import Path
import sys,re,collections
sys.stdout.reconfigure(encoding=\"utf-8\")
root=Path(\"docs/planning\")
files=[p for p in root.rglob(\"*.md\") if \"archive\" not in p.parts]
bad_links=[]
for p in files:
 for n,line in enumerate(p.read_text(encoding=\"utf-8\").splitlines(),1):
  for m in re.finditer(r\"\\[["'^'"\\]]+\\]\\((["'^)]+)'"\\)\",line):
   url=m.group(1)
   if \"://\" not in url and not url.startswith(\"#\") and not (p.parent/url).exists():bad_links.append((str(p.relative_to(root)),n,url))
print(\"broken markdown links:\",bad_links)
for pat in [r\"R\\d+[A-Z]-\\d+\",r\"STEP\\s*\\d+\",r\"결정 전 기본|철회|당시|과거 권고|Codex 권고|Claude 제안|미재검증|양측 입장|계획 수립 단계\"]:
 hits=[]
 for p in files:
  for n,line in enumerate(p.read_text(encoding=\"utf-8\").splitlines(),1):
   if re.search(pat,line):hits.append((str(p.relative_to(root)),n,line[:130]))
 print(\"residue\",pat,len(hits),hits[:15])
for p in files:
 for n,line in enumerate(p.read_text(encoding=\"utf-8\").splitlines(),1):
  if \"S0\" in line and \"S01\" not in line: print(\"S0\",p.relative_to(root),n,line[:240])
'@ | python -"

